-- Généré par tests/build_guide.lua depuis GUIDE.deDE.md : ne pas éditer à la main.
local _, NS = ...
NS.guides = NS.guides or {}
NS.guides.deDE = {
    { "h1", "Panorama-Anleitung" },
    { "p", "So benutzt du Panorama auf WoW Forever und richtest HDR unter Windows ein." },
    { "p", "|cffffd100Sichere zuerst deine Einstellungen.|r Panorama ändert Spieleinstellungen, und das Entfernen des Addons setzt sie nicht zurück. Bevor du etwas änderst, beende das Spiel und kopiere den Ordner |cffffd100WTF|r deiner Spielinstallation an einen sicheren Ort. Um zurückzukehren, beende das Spiel und lege diese Kopie wieder an ihren Platz." },
    { "h2", "1. Das Fenster öffnen" },
    { "li", "Gib |cffffd100/pano|r ein oder klicke mit der linken Maustaste auf den Panorama-Button an der Minimap.", "-" },
    { "li", "Unter Optionen > AddOns > Panorama gibt es ebenfalls einen Button, der es öffnet.", "-" },
    { "li", "Ziehe die Titelleiste, um das Fenster zu verschieben. Escape oder der Schließen-Button schließt es.", "-" },
    { "p", "Der Minimap-Button:" },
    { "li", "Linksklick öffnet oder schließt das Fenster.", "-" },
    { "li", "Rechtsklick zeigt die Voreinstellungen, Rückgängig, Wiederholen und den Neustart der Grafik.", "-" },
    { "li", "Ziehe ihn, um ihn um die Minimap zu bewegen. |cffffd100/pano minimap|r zeigt oder versteckt ihn.", "-" },
    { "h2", "2. Das Fenster" },
    { "row", "|cffffd100Einfach|r, |cffffd100Erweitert|r (neben dem Titel)", "Einfach: Jeder Reiter zeigt eine kurze Liste der wichtigsten Einstellungen, ohne Abschnitte. Erweitert: alle Einstellungen, nach Abschnitten, mit den Regeln pro Ort und dem Abschnitt Experten. Bei der Erstinstallation ist es Einfach; wenn du Panorama schon benutzt hast, ist es Erweitert. Die Suche findet immer alle Einstellungen." },
    { "row", "Anleitung (oben rechts)", "Öffnet diese Anleitung im Spiel." },
    { "row", "Menü |cffffd100Optionen|r (oben rechts)", "|cffffd100Sprache|r (Spielsprache oder eine von zehn Sprachen; eine Änderung lädt die Oberfläche neu), |cffffd100Bei jedem Einloggen anwenden|r, |cffffd100Minimap-Button|r, |cffffd100Alles zurücksetzen…|r." },
    { "row", "|cffffd100Aktuelles Aussehen:|r (Leiste unter dem Titel)", "Das Aussehen, das gerade auf der Welt liegt, und wer es vorgibt: du, Tag und Nacht oder der Ort. Ihr Button (|cffffd100Bearbeiten|r, |cffffd100Diese Regel bearbeiten|r) öffnet die Stelle, an der du es änderst. Fahre mit der Maus über die Leiste, um zu sehen, was Vorrang hat." },
    { "row", "Reiter", "|cffffd100Bild|r (Grafikqualität), |cffffd100HDR|r, |cffffd100Stimmung|r (Aussehen der Welt), |cffffd100Meine Filter|r. Der geöffnete Reiter wird gespeichert." },
    { "row", "Suchfeld (rechts neben den Reitern)", "Gib ein Wort ein, um die passenden Einstellungen aller Reiter aufzulisten. Leere es, um zurückzukehren." },
    { "row", "Voreinstellungen (Reiter Bild)", "Niedrig, Mittel, Hoch, Extra. Die Voreinstellung, die zu deinen Einstellungen passt, ist hervorgehoben." },
    { "row", "Fußzeile", "|cffffd100Rückgängig|r macht deine letzte Änderung rückgängig: Regler, Feld, Voreinstellung, Filter, Stimmung oder Alles zurücksetzen. |cffffd100Wiederholen|r stellt sie wieder her. Die letzten 20 Änderungen bleiben bis |cffffd100/reload|r erhalten. |cffffd100Neu starten|r startet die Grafik-Engine neu." },
    { "p", "Klicke im Modus Erweitert auf einen Abschnittstitel, um ihn ein- oder auszuklappen. Der Abschnitt |cffffd100Experten (nur Konsole)|r ist zunächst eingeklappt. Ein Abschnittstitel zeigt, wie viele seiner Einstellungen du geändert hast." },
    { "h3", "Eine Einstellungszeile" },
    { "li", "|cffffd100Schieberegler|r: Der Wert wird geschrieben, wenn du die Maustaste loslässt, nicht während du ziehst.", "-" },
    { "li", "|cffffd100Wertfeld|r neben dem Regler: Gib einen Wert ein und drücke dann Enter oder klicke woanders hin. Escape bricht ab, Tab springt zum nächsten Feld. Ein Komma funktioniert als Dezimaltrennzeichen. Der Wert bleibt im Bereich des Reglers.", "-" },
    { "li", "|cffffd100Standard-Button|r: setzt diese Einstellung auf ihren Standardwert zurück. Fahre mit der Maus darüber, um den Wert zu sehen.", "-" },
    { "li", "|cffffd100Goldene Markierung|r links: Du hast diese Einstellung geändert.", "-" },
    { "li", "|cffffd100Spielmenü|r: Wenn ein Spielmenü diesen Wert ebenfalls setzt, nennt die Hilfe der Beschriftung es. Dieses Menü liest den Wert nicht zurück, es kann also eine andere Stufe zeigen.", "-" },
    { "li", "|cffffd100Ausgegraute Zeile|r: Sie hängt von einer anderen Einstellung ab, die aus ist (zum Beispiel |cffffd100Qualität des volumetrischen Nebels|r ohne |cffffd100Volumetrischer Nebel|r, Farbtonstärke ohne Farbton), oder ein Modus legt sie fest. Fahre mit der Maus über die Beschriftung, um den Grund zu sehen. Eine Zeile, die von einer anderen abhängt, ist nach rechts eingerückt, direkt unter ihr.", "-" },
    { "li", "Fahre mit der Maus über eine Beschriftung, um die ganze Hilfe zu lesen.", "-" },
    { "h2", "3. Voreinstellungen" },
    { "row", "Niedrig", "Beste Leistung. Kurze Sichtweite, keine Schatten." },
    { "row", "Mittel", "Ausgewogen. Gute Leistung, ordentliche Schatten." },
    { "row", "Hoch", "Stufe Hoch des Spiels. Volle Schatten, alle Effekte." },
    { "row", "Extra", "Hoch, mit der größten Sichtweite." },
    { "p", "Voreinstellungen ändern nur die Grafikqualitäts-Einstellungen im Reiter Bild. Sie ändern nicht Kamera, Maus, Oberfläche, Schärfung, niedrige Latenz, HDR oder Filter." },
    { "p", "Anders überlegt? |cffffd100Rückgängig|r (Fußzeile, oder |cffffd100/pano undo|r) stellt die Einstellungen von vor der Voreinstellung wieder her." },
    { "h2", "4. Stimmung" },
    { "p", "Der Reiter Stimmung legt das Aussehen der Welt fest: Effekte über dem Bild. Sie ändern keine Spieleinstellung." },
    { "li", "|cffffd100Modus|r (oben im Reiter): |cffffd100Fest|r (derselbe Filter überall), |cffffd100Tag und Nacht|r (ein Tagfarbton und ein Nachtfarbton) oder |cffffd100Nach Ort|r (siehe unten). Standardmäßig Fest.", "-" },
    { "li", "|cffffd100Hier|r: der Ort und die Tageszeit, die gerade erkannt werden. Hat ein Dungeon, ein Innenraum oder das Wetter Vorrang vor einer von dir eingestellten Zone, wird das angezeigt.", "-" },
    { "li", "|cffffd100Filter|r (Modi Fest und Tag und Nacht): |cffffd100Basis|r nutzt die Zeilen darunter. Einer deiner Filter (Reiter Meine Filter) ersetzt Farbton, Vignette und Filmkorn und bringt seinen Kontrast, seine Helligkeit und sein Gamma mit. |cffffd100Filter bearbeiten|r öffnet ihn im Reiter Meine Filter.", "-" },
    { "li", "|cffffd100Farbton|r: Klicke auf eine Vorschau, um ihn sofort anzuwenden (Sepia, Warm, Kalt, Nacht, Smaragd, Dämmerung). |cffffd100Farbtonstärke|r legt fest, wie stark er ist.", "-" },
    { "li", "|cffffd100Vignette|r: dunkelt die Bildschirmränder ab.", "-" },
    { "li", "|cffffd100Filmkorn|r: animiertes Korn.", "-" },
    { "li", "|cffffd100Tagfarbton|r und |cffffd100Nachtfarbton|r (Modus Tag und Nacht): Panorama legt tagsüber den Tagfarbton und nachts den Nachtfarbton auf, nach Tag und Nacht des Spiels. Sie ersetzen den Farbton. Der Wechsel erfolgt allmählich von 19 bis 21 Uhr und von 5 bis 7 Uhr (Serverzeit). Einer deiner Filter, den du in der Zeile Filter wählst, ersetzt sie.", "-" },
    { "li", "|cffffd100Himmel|r: dieselben Farben als Verlauf, oben am Bildschirm voll und unten heller. |cffffd100Himmelsstärke|r legt fest, wie stark er ist.", "-" },
    { "li", "|cffffd100Schwarze Balken|r: Balken oben und unten, jeweils 0 bis 20 % des Bildschirms, in jedem Modus. Das Spiel rendert weiterhin, was sie verdecken, daher steigern sie die Bildrate nicht.", "-" },
    { "p", "Im Modus Einfach zeigt der Reiter den Modus, den Ort, den Filter, den Farbton und seine Stärke sowie die Tag- und Nachtfarbtöne. Vignette, Filmkorn, Himmel und schwarze Balken gibt es im Modus Erweitert." },
    { "h3", "Nach Ort" },
    { "p", "Im Modus |cffffd100Nach Ort|r ändern sich Tönung, Himmel, Vignette und Körnung von selbst, passend zu deinem Ort." },
    { "li", "Die Zeilen des Modus Fest sind ausgeblendet: Die Regel des Ortes ersetzt sie. Nur die schwarzen Balken bleiben. Ihre Werte bleiben gespeichert und kehren zurück, wenn du den Modus wechselst. Im Modus Einfach gelten die mitgelieferten Regeln; wähle Erweitert, um sie zu bearbeiten.", "-" },
    { "li", "|cffffd100Ort|r: legt Tönung, Vignette und Körnung fest. Reihenfolge: Dungeon oder Schlachtzug, Innenraum, Wetter (Regen, Schnee, Sandsturm), dann die Art der Zone: gemäßigte Lande, Wüsten und Ödland, Schneelande, Dschungel und Sumpf, verderbte Lande, Vulkanlande, Arkane Wälder. Eine noch unbekannte Zone zählt als gemäßigt. Wetter zählt nur, wenn die Wetterintensität über 0 liegt.", "-" },
    { "li", "|cffffd100Tageszeit|r: legt den Himmel fest (Tag, Morgen- und Abenddämmerung, Nacht). Die Nacht folgt Tag und Nacht des Spiels, die Dämmerung der Serverzeit. Kein Himmel in Innenräumen oder im Dungeon.", "-" },
    { "li", "|cffffd100Regel|r (Modus Erweitert): wähle eine Regel und stelle sie darunter ein. Der Button Standard gibt den mitgelieferten Wert dieser Regel zurück. Wenn sich das Fenster zum ersten Mal öffnet, ist die Regel des Ortes, an dem du bist, geöffnet. Das Menü hat fünf Gruppen: |cffffd100Zonen|r (die Zone, in der du bist, und die von dir eingestellten Zonen), |cffffd100Dungeon und Innenraum|r, |cffffd100Wetter|r, |cffffd100Zonentyp|r und |cffffd100Himmel (Tageszeit)|r. Die ersten vier stellen Tönung, Vignette, Körnung und eine Grafikvoreinstellung ein: Es gilt immer nur ein Ort, in der oben genannten Reihenfolge. Die letzte stellt den Himmel ein. Für den Anfang musst du nichts einstellen: Jede Regel hat bereits ihre Werte.", "-" },
    { "li", "|cffffd100Diese Zone|r: erste Wahl desselben Menüs, mit dem Namen der Zone, in der du dich befindest. Wähle sie, um dieser Zone eine eigene Tönung, Vignette und Körnung zu geben, ausgehend von ihrer Art der Zone. Sie hat dann Vorrang vor der Art der Zone, aber nach Dungeon, Innenraum und Wetter. Die Zonen, die du eingestellt hast, bleiben im Menü. |cffffd100Zurück zum Zonentyp|r (neben dem Menü) entfernt die Werte der Zone: sie folgt wieder ihrer Art der Zone.", "-" },
    { "li", "|cffffd100Alle Zonen|r: Untermenü desselben Menüs, mit allen bekannten Zonen. Wähle eine, um sie einzustellen, ohne dort zu sein. Die Zonen sind nach Kontinent geordnet.", "-" },
    { "li", "|cffffd100Voreinstellung|r und |cffffd100Sichtweite der Umgebung|r (Abschnitt |cffffd100Bild|r eines Ortes oder einer Zone): Sie gelten, solange du an diesem Ort bist, über deinen eigenen Einstellungen, in jedem Stimmungsmodus. Die Sichtweite des Ortes hat Vorrang vor der Sichtweite der Voreinstellung. Deine eigenen Einstellungen bleiben gespeichert und kommen zurück, wenn du gehst. |cffffd100Meine Einstellungen|r ändert nichts. Beispiel: Niedrig in Dungeons, Extra in einer Zone, die du magst. In einem Dungeon oder Schlachtzug stellt die erste Auswahl des Menüs nur diesen Dungeon ein. Im Reiter Bild erscheint neben den Voreinstellungen |cffffd100Hier: …|r, solange ein Ort eigene Werte vorgibt; im Modus Erweitert öffnet es diese Regel. Im Kampf wartet die Änderung bis zum Ende des Kampfes.", "-" },
    { "li", "|cffffd100Filter|r (erste Zeile des Abschnitts |cffffd100Aussehen|r eines Ortes oder einer Zone): Dieser Ort nutzt einen deiner Filter aus dem Reiter Meine Filter, mit dessen Kontrast, Helligkeit und Gamma. |cffffd100Einstellungen unten|r: Tönung, Vignette und Körnung der Regel. Der Abschnitt Aussehen gilt nur im Modus Nach Ort.", "-" },
    { "h2", "5. Meine Filter" },
    { "p", "Im Reiter Meine Filter kannst du beliebig viele eigene Filter erstellen. Der geöffnete Filter wird auf der Welt nur als Vorschau gezeigt; der angewendete wird im Tab Stimmung gewählt. |cffffd100Neu|r fügt einen hinzu und öffnet ihn, |cffffd100Löschen|r entfernt den geöffneten: der Filter des Reiters Stimmung und die Regeln, die ihn nutzten, wechseln zu keinem Filter. Ein Filter bleibt immer erhalten." },
    { "li", "|cffffd100Filter|r: wählt den Filter, den die Zeilen darunter einstellen. |cffffd100Name|r: gib ihm einen Namen (Enter zum Bestätigen).", "-" },
    { "li", "|cffffd100Farbton|r: Klicke auf eine Vorschau, um dem Filter diese Farbe zu geben. |cffffd100Rot|r, |cffffd100Grün|r, |cffffd100Blau|r (in %): seine genaue Farbe. |cffffd100Farbtonstärke|r: seine Stärke.", "-" },
    { "li", "|cffffd100Vignette|r und |cffffd100Filmkorn|r: die des Filters.", "-" },
    { "li", "|cffffd100Kontrast|r, |cffffd100Helligkeit|r, |cffffd100Gamma|r: Bildeinstellungen, die der Filter dem Spiel gibt, solange er angewendet wird; deine eigenen Werte kehren danach zurück. Meine Einstellungen: nichts ändert sich. Je nach Anzeigemodus können sie wirkungslos bleiben.", "-" },
    { "li", "Im Modus Einfach zeigt der Reiter nur den Farbton und die Farbtonstärke.", "-" },
    { "li", "Solange der Reiter geöffnet ist, ist der angezeigte Filter live im Spiel zu sehen. Die Leiste |cffffd100Aktuelles Aussehen:|r sagt, wenn es nur eine Vorschau ist.", "-" },
    { "li", "So nutzt du einen Filter: Wähle ihn in der Zeile |cffffd100Filter|r des Reiters Stimmung (Modi Fest und Tag und Nacht) oder für einen Ort oder eine Zone (Modus Nach Ort). Er ersetzt dann Farbton, Vignette und Filmkorn. |cffffd100Basis|r oder |cffffd100Einstellungen unten|r: nichts ändert sich.", "-" },
    { "h2", "6. Deine Werte und das Spiel" },
    { "li", "Bei der ersten Installation liest Panorama deine aktuellen Spieleinstellungen. Nichts ändert sich, bis du ein Steuerelement bewegst.", "-" },
    { "li", "Eine Änderung im Grafikmenü des Spiels oder mit |cffffd100/console|r wird im Fenster angezeigt.", "-" },
    { "li", "|cffffd100Bei jedem Einloggen anwenden|r (Menü Optionen, standardmäßig an): Die Einstellungen, die du in Panorama geändert hast, werden bei jedem Einloggen erneut geschrieben. Die anderen folgen dem Grafikmenü des Spiels.", "-" },
    { "li", "Eine Änderung im Kampf wird am Ende des Kampfes angewendet.", "-" },
    { "li", "Einige Einstellungen, wie MSAA, brauchen einen Neustart der Grafik. Klicke in der Fußzeile auf |cffffd100Neu starten|r oder gib |cffffd100/pano restart|r ein. Der Bildschirm flackert eine Sekunde lang.", "-" },
    { "h2", "7. HDR unter Windows" },
    { "p", "HDR-Einstellungen gibt es im Spiel nur als Konsolenbefehle. Panorama zeigt sie im Reiter |cffffd100HDR|r. Du brauchst einen Monitor, der HDR unterstützt." },
    { "h3", "Schritt 1: HDR in Windows einschalten" },
    { "p", "Windows 11:" },
    { "li", "Öffne |cffffd100Einstellungen > System > Bildschirm|r.", "1." },
    { "li", "Wähle den HDR-Monitor aus, wenn du mehrere hast.", "2." },
    { "li", "Schalte |cffffd100HDR verwenden|r ein. Mit der Tastenkombination |cffffd100Win + Alt + B|r schaltest du es ebenfalls ein oder aus.", "3." },
    { "p", "Windows 10: |cffffd100Einstellungen > System > Bildschirm > Windows-HD-Farbeinstellungen|r (Windows HD Color settings), dann |cffffd100HDR-Spiele und -Apps wiedergeben|r (Play HDR games and apps) einschalten." },
    { "p", "Prüfe außerdem, ob HDR im eigenen Menü des Monitors an ist, falls es dort diese Option gibt." },
    { "p", "Schalte |cffffd100Automatisches HDR|r (Auto HDR) von Windows 11 aus: |cffffd100Einstellungen > System > Bildschirm > HDR|r. Es ist für Spiele ohne HDR gedacht. WoW erzeugt sein eigenes HDR-Bild." },
    { "h3", "Schritt 2: Die Spitzenhelligkeit deines Monitors finden" },
    { "p", "Installiere die kostenlose App |cffffd100Windows-HDR-Kalibrierung|r (Windows HDR Calibration) aus dem Microsoft Store und starte sie. Die maximale Leuchtdichte, die sie findet, ist die Spitzenhelligkeit deines Monitors in Nits." },
    { "p", "Ohne die App nimm die HDR-Einstufung des Monitors: DisplayHDR 400 bedeutet etwa 400 Nits, DisplayHDR 600 etwa 600, DisplayHDR 1000 etwa 1000." },
    { "h3", "Schritt 3: HDR in Panorama einstellen" },
    { "p", "Öffne |cffffd100/pano|r, Reiter |cffffd100HDR|r. Im Modus Einfach zeigt der Reiter nur die ersten drei Zeilen unten: wähle |cffffd100Erweitert|r, um |cffffd100HDR-Intensität|r und die Referenzhelligkeit zu sehen." },
    { "li", "Aktiviere |cffffd100HDR-Ausgabe|r.", "1." },
    { "li", "Aktiviere |cffffd100Spitzenhelligkeit verwenden|r oder |cffffd100Referenzhelligkeit verwenden|r: einen von beiden, nie beide. Ohne einen wird das Bild dunkel.", "2." },
    { "p", "|cffffd100Spitzenhelligkeitsmodus (empfohlen)|r" },
    { "li", "Aktiviere |cffffd100Spitzenhelligkeit verwenden|r.", "-" },
    { "li", "Stelle |cffffd100Spitzenhelligkeit (Nits)|r auf den Wert aus Schritt 2.", "-" },
    { "li", "|cffffd100HDR-Intensität|r wirkt nur in diesem Modus. Der Standardwert des Spiels ist 2. Ändere ihn in kleinen Schritten und vergleiche: Blizzard dokumentiert seine genaue Wirkung nicht.", "-" },
    { "p", "|cffffd100Referenzhelligkeitsmodus|r" },
    { "li", "Aktiviere |cffffd100Referenzhelligkeit verwenden|r.", "-" },
    { "li", "|cffffd100Referenzhelligkeit (Nits)|r ist die Helligkeit von Weiß in der Szene. 203 ist der Standardwert. Erhöhe ihn, wenn das Bild in einem hellen Raum zu dunkel wirkt. HDR-Intensität hat in diesem Modus keine Wirkung.", "-" },
    { "p", "Wenn sich das Bild nicht ändert, klicke in der Fußzeile auf |cffffd100Neu starten|r." },
    { "h3", "HDR-Fehlerbehebung" },
    { "row", "Bild sehr dunkel", "Aktiviere einen der beiden Helligkeitsmodi." },
    { "row", "Bild grau oder verwaschen", "Schalte HDR in Windows (Schritt 1) und im Menü des Monitors ein." },
    { "row", "Automatisches HDR in Windows an", "Schalte es aus (Schritt 1)." },
    { "row", "Lichter zu hell oder flach", "Stelle die Spitzenhelligkeit auf den echten Wert deines Monitors (Schritt 2)." },
    { "row", "Du willst HDR aus", "Deaktiviere |cffffd100HDR-Ausgabe|r." },
    { "p", "Jede HDR-Zeile hat einen Standard-Button, der den Wert des Spiels wiederherstellt." },
    { "h2", "8. Befehle" },
    { "row", "|cffffd100/pano|r", "Das Fenster öffnen oder schließen" },
    { "row", "|cffffd100/pano low|r, |cffffd100/pano medium|r, |cffffd100/pano high|r, |cffffd100/pano extra|r", "Eine Voreinstellung anwenden" },
    { "row", "|cffffd100/pano undo|r", "Die letzte Änderung rückgängig machen" },
    { "row", "|cffffd100/pano redo|r", "Die gerade rückgängig gemachte Änderung wiederherstellen" },
    { "row", "|cffffd100/pano reset|r", "Jede Einstellung und jeden Filter auf Standard zurücksetzen" },
    { "row", "|cffffd100/pano status|r", "Zeigt im Chat den erkannten Ort, die Tageszeit und die gerade angewendeten Filter (während einer Überblendung die Zielwerte)" },
    { "row", "|cffffd100/pano apply|r", "In Panorama geänderte Einstellungen erneut schreiben" },
    { "row", "|cffffd100/pano restart|r", "Die Grafik-Engine neu starten" },
    { "row", "|cffffd100/pano minimap|r", "Den Minimap-Button zeigen oder verstecken" },
    { "row", "|cffffd100/pano blackbars 10|r", "Schwarze Balken mit 10 % der Bildschirmhöhe (0 bis 20). |cffffd100off|r entfernt sie" },
    { "row", "|cffffd100/pano grain 10|r", "Filmkorn auf 10 (0 bis 100). |cffffd100off|r entfernt es" },
    { "row", "|cffffd100/pano vignette 10|r", "Vignette auf 10 (0 bis 100). |cffffd100off|r entfernt sie" },
    { "h2", "9. Zurücksetzen" },
    { "li", "Der |cffffd100Standard|r-Button in jeder Zeile setzt diese Einstellung zurück.", "-" },
    { "li", "Der Button |cffffd100Standard|r des Grafikmenüs des Spiels setzt nur die Einstellungen zurück, die dieses Menü verwaltet, und Panorama folgt ihm. Nutze für die anderen und für die Filter die Standard-Buttons in |cffffd100/pano|r.", "-" },
    { "li", "|cffffd100Alles zurücksetzen…|r (Menü Optionen, mit Bestätigung) oder |cffffd100/pano reset|r: setzt jede Einstellung im Fenster, ob in Panorama geändert oder nicht, und jeden Filter auf den Standard zurück. |cffffd100Rückgängig|r macht es bis |cffffd100/reload|r rückgängig. Der Reiter Stimmung und die eingestellten Zonen werden ebenfalls zurückgesetzt. Deine Filter im Reiter Meine Filter werden ebenfalls gelöscht.", "-" },
}
